"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useState } from "react";
import { MODES, MODE_KEYS } from "@/lib/modes";
import { MODE_ICONS } from "@/components/ui/Icons";
import { useAuth } from "@/context/AuthContext";
import { supabase } from "@/lib/supabase";
import PhotoUpload from "@/components/app/PhotoUpload";

export default function RegisterPage() {
  const router = useRouter();
  const { signUp, loading: authLoading, error: authError } = useAuth();
  const [step, setStep] = useState(1);
  const [name, setName] = useState("");
  const [age, setAge] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [gender, setGender] = useState("");
  const [lookingFor, setLookingFor] = useState("");
  const [modes, setModes] = useState<string[]>([]);
  const [bio, setBio] = useState("");
  const [error, setError] = useState("");
  const [tempUserId, setTempUserId] = useState<string | null>(null);
  const [photoUploaded, setPhotoUploaded] = useState(false);

  const toggleMode = (k: string) => setModes(p => p.includes(k) ? p.filter(m => m !== k) : [...p, k]);

  // Create account at end of step 2 so photo upload (step 3) has an authenticated user
  async function handleCreateAccount() {
    setError("");

    const user = await signUp(email, password, {
      name,
      age: parseInt(age),
      gender,
      looking_for: lookingFor,
    });

    if (!user) {
      setError(authError || "Erreur lors de l'inscription");
      return;
    }

    // Activate selected modes
    for (const mode of modes) {
      await supabase.from("mode_activations").insert({
        user_id: user.id,
        mode,
        is_active: true,
        available_time: "Dispo maintenant",
      });
    }

    setTempUserId(user.id);
    setStep(3);
  }

  // Final step: save bio and redirect
  async function handleFinish(e: React.FormEvent) {
    e.preventDefault();
    if (!tempUserId) return;

    if (bio) {
      await supabase.from("profiles").update({ bio }).eq("id", tempUserId);
    }

    router.push("/onboarding");
  }

  return (
    <main className="min-h-screen bg-bg flex flex-col items-center px-6 py-10">
      <div className="w-full max-w-sm">
        <div className="flex items-center justify-center gap-2 mb-6">
          <span className="text-2xl text-accent" aria-hidden="true">â˜¾</span>
          <span className="text-xl font-bold">CeSoir</span>
        </div>

        {/* Progress */}
        <div className="flex gap-1.5 mb-6" role="progressbar" aria-valuenow={step} aria-valuemin={1} aria-valuemax={4} aria-label={`Etape ${step} sur 4`}>
          {[1,2,3,4].map(s => (
            <div key={s} className={`h-1 flex-1 rounded-full ${s <= step ? "gradient-bg" : "bg-border"}`} />
          ))}
        </div>

        {/* Error */}
        {(error || authError) && (
          <div role="alert" className="bg-danger/10 border border-danger/20 text-danger text-[13px] px-4 py-3 rounded-xl mb-4">
            {error || authError}
          </div>
        )}

        {/* Step 1 */}
        {step === 1 && (
          <div className="animate-fade-up">
            <h1 className="text-xl font-bold mb-1">Cree ton profil</h1>
            <p className="text-sm text-text-muted mb-6">30 secondes, promis.</p>
            <div className="space-y-4">
              <div className="grid grid-cols-[1fr_80px] gap-3">
                <div>
                  <label htmlFor="reg-name" className="block text-[11px] font-semibold text-text-muted mb-1">Prenom</label>
                  <input id="reg-name" type="text" required placeholder="Ton prenom" value={name} onChange={e => setName(e.target.value)} autoComplete="given-name" className="w-full px-3 py-3 bg-bg border border-border rounded-xl text-sm text-text" />
                </div>
                <div>
                  <label htmlFor="reg-age" className="block text-[11px] font-semibold text-text-muted mb-1">Age</label>
                  <input id="reg-age" type="number" min={18} max={99} required placeholder="25" value={age} onChange={e => setAge(e.target.value)} className="w-full px-3 py-3 bg-bg border border-border rounded-xl text-sm text-text" />
                </div>
              </div>
              <div>
                <label htmlFor="reg-email" className="block text-[11px] font-semibold text-text-muted mb-1">Email</label>
                <input id="reg-email" type="email" required placeholder="ton@email.com" value={email} onChange={e => setEmail(e.target.value)} autoComplete="email" className="w-full px-3 py-3 bg-bg border border-border rounded-xl text-sm text-text" />
              </div>
              <div>
                <label htmlFor="reg-pass" className="block text-[11px] font-semibold text-text-muted mb-1">Mot de passe</label>
                <input id="reg-pass" type="password" required minLength={6} placeholder="Min. 6 caracteres" value={password} onChange={e => setPassword(e.target.value)} autoComplete="new-password" className="w-full px-3 py-3 bg-bg border border-border rounded-xl text-sm text-text" />
              </div>
              <fieldset>
                <legend className="text-[11px] font-semibold text-text-muted mb-2">Je suis</legend>
                <div className="grid grid-cols-3 gap-2">
                  {[{v:"homme",l:"Homme"},{v:"femme",l:"Femme"},{v:"autre",l:"Autre"}].map(g => (
                    <button key={g.v} type="button" onClick={() => setGender(g.v)} aria-pressed={gender === g.v}
                      className={`py-3 rounded-xl text-sm font-medium border transition-all tap-target ${gender === g.v ? "border-accent gradient-bg text-white" : "border-border text-text-muted"}`}>
                      {g.l}
                    </button>
                  ))}
                </div>
              </fieldset>
              <fieldset>
                <legend className="text-[11px] font-semibold text-text-muted mb-2">Je cherche</legend>
                <div className="grid grid-cols-3 gap-2">
                  {[{v:"hommes",l:"Hommes"},{v:"femmes",l:"Femmes"},{v:"tous",l:"Tout le monde"}].map(g => (
                    <button key={g.v} type="button" onClick={() => setLookingFor(g.v)} aria-pressed={lookingFor === g.v}
                      className={`py-3 rounded-xl text-sm font-medium border transition-all tap-target ${lookingFor === g.v ? "border-accent gradient-bg text-white" : "border-border text-text-muted"}`}>
                      {g.l}
                    </button>
                  ))}
                </div>
              </fieldset>
              <button type="button" onClick={() => setStep(2)} disabled={!gender || !lookingFor || !name || !email || !password || !age}
                className="w-full gradient-bg text-white py-3.5 rounded-full text-sm font-semibold disabled:opacity-40 active:scale-[0.98] transition-transform tap-target">
                Suivant
              </button>
            </div>
          </div>
        )}

        {/* Step 2 */}
        {step === 2 && (
          <div className="animate-fade-up">
            <h1 className="text-xl font-bold mb-1">Tes modes ce soir</h1>
            <p className="text-sm text-text-muted mb-6">Choisis un ou plusieurs modes.</p>
            <div className="grid grid-cols-3 gap-2 mb-6" role="group" aria-label="Selection des modes">
              {MODE_KEYS.map(k => {
                const m = MODES[k];
                const on = modes.includes(k);
                const Icon = MODE_ICONS[k];
                return (
                  <button key={k} type="button" onClick={() => toggleMode(k)} aria-pressed={on}
                    className={`flex flex-col items-center gap-1 p-3 rounded-xl border transition-all tap-target ${on ? "border-accent gradient-bg-subtle" : "border-border"}`}>
                    {Icon ? <Icon size={20} className={on ? "text-accent" : "text-text-muted"} /> : <span className="text-xl">{m.icon}</span>}
                    <span className={`text-[9px] font-medium ${on ? "text-accent" : "text-text-muted"}`}>{m.name}</span>
                  </button>
                );
              })}
            </div>
            <div className="flex gap-3">
              <button type="button" onClick={() => setStep(1)} className="flex-1 py-3.5 rounded-full text-sm font-medium border border-border tap-target">Retour</button>
              <button type="button" onClick={handleCreateAccount} disabled={modes.length === 0 || authLoading}
                className="flex-1 gradient-bg text-white py-3.5 rounded-full text-sm font-semibold disabled:opacity-40 active:scale-[0.98] transition-transform tap-target">
                {authLoading ? "Creation..." : "Suivant"}
              </button>
            </div>
            <p className="text-[10px] text-text-muted text-center mt-4 leading-relaxed">
              En t&apos;inscrivant, tu acceptes nos <Link href="/cgu" className="text-accent underline">CGU</Link> et notre <Link href="/privacy" className="text-accent underline">Politique de confidentialite</Link>.
            </p>
          </div>
        )}

        {/* Step 3 â€” Photo (optional) */}
        {step === 3 && tempUserId && (
          <div className="animate-fade-up">
            <h1 className="text-xl font-bold mb-1">Ajoute ta photo</h1>
            <p className="text-sm text-text-muted mb-8">Les profils avec photo recoivent 3x plus de matchs.</p>
            <PhotoUpload
              userId={tempUserId}
              onUploadComplete={() => setPhotoUploaded(true)}
            />
            <div className="flex gap-3 mt-8">
              <button type="button" onClick={() => setStep(4)}
                className="flex-1 py-3.5 rounded-full text-sm font-medium border border-border text-text-muted tap-target">
                Passer
              </button>
              <button type="button" onClick={() => setStep(4)} disabled={!photoUploaded}
                className="flex-1 gradient-bg text-white py-3.5 rounded-full text-sm font-semibold disabled:opacity-40 active:scale-[0.98] transition-transform tap-target">
                Suivant
              </button>
            </div>
          </div>
        )}

        {/* Step 4 â€” Bio */}
        {step === 4 && (
          <form onSubmit={handleFinish} className="animate-fade-up">
            <h1 className="text-xl font-bold mb-1">Parle de toi</h1>
            <p className="text-sm text-text-muted mb-6">Qu&apos;est-ce qui te rend unique ?</p>
            <div className="space-y-4">
              <div>
                <label htmlFor="reg-bio" className="block text-[11px] font-semibold text-text-muted mb-1">Ta soiree ideale</label>
                <textarea id="reg-bio" rows={3} placeholder="Ex: Un bon sushi avec quelqu'un de cool..." value={bio} onChange={e => setBio(e.target.value)}
                  className="w-full px-3 py-3 bg-bg border border-border rounded-xl text-sm text-text resize-none" />
              </div>
              <div className="flex gap-3">
                <button type="button" onClick={() => setStep(3)} className="flex-1 py-3.5 rounded-full text-sm font-medium border border-border tap-target">Retour</button>
                <button type="submit"
                  className="flex-1 gradient-bg text-white py-3.5 rounded-full text-sm font-semibold active:scale-[0.98] transition-transform tap-target">
                  C&apos;est parti !
                </button>
              </div>
            </div>
          </form>
        )}

        <p className="text-sm text-text-muted text-center mt-6">
          Deja inscrit ? <Link href="/login" className="text-accent font-semibold">Se connecter</Link>
        </p>
      </div>
    </main>
  );
}

"use client";

import { useState, useCallback } from "react";
import { motion, MotionValue } from "framer-motion";
import { Profile } from "@/lib/mock-profiles";
import { MODES, ModeKey } from "@/lib/modes";
import { MODE_ICONS } from "@/components/ui/Icons";
import SmartQueueBadge from "@/components/app/SmartQueueBadge";

interface SwipeCardProps {
  profile: Profile;
  index: number;
  total: number;
  expanded: boolean;
  onToggleExpand: () => void;
  x: MotionValue<number>;
  rotate: MotionValue<number>;
  likeOpacity: MotionValue<number>;
  nopeOpacity: MotionValue<number>;
  onDragEnd: (_: unknown, info: { offset: { x: number }; velocity: { x: number } }) => void;
  onLike: () => void;
  onReport?: () => void;
  onPass: () => void;
}

export default function SwipeCard({
  profile: p,
  index,
  total,
  expanded,
  onToggleExpand,
  x,
  rotate,
  likeOpacity,
  nopeOpacity,
  onDragEnd,
  onLike,
  onPass,
  onReport,
}: SwipeCardProps) {
  const ModeIcon = MODE_ICONS[p.mode];

  // Multi-photo carousel state
  // photos array: profile photos + one "info" slide at the end
  const photoList = p.photos && p.photos.length > 0 ? p.photos : [p.photo];
  const totalSlides = photoList.length + 1; // +1 for info slide
  const [photoIdx, setPhotoIdx] = useState(0);
  const isInfoSlide = photoIdx === photoList.length;

  const goNextPhoto = useCallback((e: React.MouseEvent | React.TouchEvent) => {
    e.stopPropagation();
    if (photoIdx < totalSlides - 1) {
      setPhotoIdx(photoIdx + 1);
    }
  }, [photoIdx, totalSlides]);

  const goPrevPhoto = useCallback((e: React.MouseEvent | React.TouchEvent) => {
    e.stopPropagation();
    if (photoIdx > 0) {
      setPhotoIdx(photoIdx - 1);
    }
  }, [photoIdx]);

  const handleCardClick = useCallback((e: React.MouseEvent) => {
    // Get click position relative to the card
    const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
    const clickX = e.clientX - rect.left;
    const cardWidth = rect.width;

    // Left third = prev photo, right third = next photo, middle = toggle expand
    if (clickX < cardWidth * 0.33) {
      if (photoIdx > 0) {
        setPhotoIdx(photoIdx - 1);
        return;
      }
    } else if (clickX > cardWidth * 0.67) {
      if (photoIdx < totalSlides - 1) {
        setPhotoIdx(photoIdx + 1);
        return;
      }
    }

    // Middle area or no navigation possible: toggle expand
    onToggleExpand();
  }, [photoIdx, totalSlides, onToggleExpand]);

  return (
    <motion.div
      className="relative w-full h-full rounded-[28px] overflow-hidden select-none z-[2]"
      style={{ x, rotate, cursor: "grab" }}
      drag="x"
      dragConstraints={{ left: 0, right: 0 }}
      dragElastic={0.7}
      onDragEnd={onDragEnd}
      onClick={handleCardClick}
      whileDrag={{ cursor: "grabbing" }}
      role="button"
      tabIndex={0}
      aria-label={`${p.name}, ${p.age} ans`}
      aria-expanded={expanded}
      onKeyDown={(e) => {
        if (e.key === "ArrowRight") onLike();
        else if (e.key === "ArrowLeft") onPass();
        else if (e.key === "ArrowUp") { e.preventDefault(); goNextPhoto(e as unknown as React.MouseEvent); }
        else if (e.key === "ArrowDown") { e.preventDefault(); goPrevPhoto(e as unknown as React.MouseEvent); }
        else if (e.key === "Enter" || e.key === " ") { e.preventDefault(); onToggleExpand(); }
      }}
    >
      {/* Photo slides */}
      {isInfoSlide ? (
        /* Last slide: info/bio on dark background */
        <div className="absolute inset-0 bg-[#111] flex flex-col justify-center p-8">
          <h2 className="text-[32px] font-black text-white mb-2">{p.name}</h2>
          <p className="text-[15px] text-white/50 mb-4">
            {p.age} ans Â· {p.distance} km Â· <span className="text-[#00FF88] font-medium">{p.time}</span>
          </p>
          <p className="text-[15px] text-white/70 leading-relaxed mb-5">{p.bio}</p>
          <ProfileTags profile={p} />
          <ExpandedDetails profile={p} />
        </div>
      ) : (
        <>
          {/* Full-bleed photo */}
          <img
            src={photoList[photoIdx]}
            alt={`Photo ${photoIdx + 1} de ${p.name}`}
            className="absolute inset-0 w-full h-full object-cover"
          />
          <div className="absolute inset-0 bg-gradient-to-t from-black via-black/40 to-transparent" />
        </>
      )}

      {/* Dot indicators at top */}
      <div className="absolute top-3 left-12 right-12 z-10 flex gap-1">
        {Array.from({ length: totalSlides }).map((_, i) => (
          <div
            key={i}
            className="flex-1 h-[3px] rounded-full transition-all duration-200"
            style={{
              backgroundColor: i === photoIdx ? "rgba(255,255,255,0.9)" : "rgba(255,255,255,0.25)",
            }}
          />
        ))}
      </div>

      {/* Swipe indicators */}
      <motion.div className="absolute top-8 left-6 z-10" style={{ opacity: likeOpacity }}>
        <div className="px-5 py-2 rounded-2xl border-2 border-[#00FF88] bg-[#00FF88]/15 backdrop-blur-sm -rotate-6">
          <span className="text-[#00FF88] text-[18px] font-black tracking-widest">LIKE</span>
        </div>
      </motion.div>
      <motion.div className="absolute top-8 right-6 z-10" style={{ opacity: nopeOpacity }}>
        <div className="px-5 py-2 rounded-2xl border-2 border-[#ff4466] bg-[#ff4466]/15 backdrop-blur-sm rotate-6">
          <span className="text-[#ff4466] text-[18px] font-black tracking-widest">NOPE</span>
        </div>
      </motion.div>

      {/* Counter + Report */}
      <div className="absolute top-5 right-5 flex items-center gap-2 z-10">
        {onReport && (
          <button
            onClick={(e) => { e.stopPropagation(); onReport(); }}
            className="bg-black/40 backdrop-blur-md rounded-full w-8 h-8 flex items-center justify-center text-white/70 text-[14px] tap-target"
            aria-label="Signaler ce profil"
          >
            Â·Â·Â·
          </button>
        )}
        <div className="bg-black/40 backdrop-blur-md rounded-full px-3 py-1.5 text-[10px] text-white/70 font-semibold">
          {index + 1} / {total}
        </div>
      </div>

      {/* Mode badge */}
      <div className="absolute top-5 left-5 z-10 flex items-center gap-1.5 bg-black/40 backdrop-blur-md rounded-full px-3 py-1.5">
        {ModeIcon && <ModeIcon size={14} className="text-white/80" />}
        <span className="text-[10px] text-white/80 font-semibold">{MODES[p.mode].name}</span>
      </div>

      {/* Smart Queue Badges - below mode badge */}
      <div className="absolute top-14 left-5 z-10">
        <SmartQueueBadge profile={p} />
      </div>

      {/* Info panel (not shown on info slide) */}
      {!isInfoSlide && (
        <div className={`absolute bottom-0 left-0 right-0 transition-all duration-300 ${expanded ? "h-[65%]" : "h-[38%]"}`}>
          <div className={`relative h-full flex flex-col justify-end p-6 ${expanded ? "overflow-y-auto" : ""}`}>
            {p.time === "Dispo maintenant" && (
              <div className="flex items-center gap-1.5 mb-3">
                <span className="w-2 h-2 rounded-full bg-[#00FF88]" />
                <span className="text-[11px] text-[#00FF88] font-bold uppercase tracking-widest">Maintenant</span>
              </div>
            )}

            <h2 className="text-[38px] font-black leading-[0.95] tracking-tight text-white mb-1">{p.name}</h2>
            <p className="text-[15px] text-white/50 font-light mb-3">
              {p.age} ans Â· {p.distance} km Â· <span className="text-[#00FF88] font-medium">{p.time}</span>
            </p>

            <p className={`text-[14px] text-white/70 leading-relaxed ${expanded ? "" : "line-clamp-2"}`}>{p.bio}</p>

            <ProfileTags profile={p} />

            {expanded && <ExpandedDetails profile={p} />}

            <div className="flex justify-center mt-3">
              <div className={`w-8 h-[3px] rounded-full bg-white/20 transition-transform ${expanded ? "rotate-180" : ""}`} />
            </div>
          </div>
        </div>
      )}
    </motion.div>
  );
}

function ProfileTags({ profile: p }: { profile: Profile }) {
  const tags: React.ReactNode[] = [];
  if (p.cuisine) tags.push(<Tag key="c" text={p.cuisine} />);
  if (p.event) tags.push(<Tag key="e" text={p.event} accent />);
  if (p.dog) tags.push(<Tag key="d" text={`${p.dog} Â· ${p.breed}`} />);
  if (p.safe) tags.push(<Tag key="s" text="Safe Space" green />);
  if (p.from) tags.push(<Tag key="f" text={p.from} />);
  if (p.speaks) tags.push(<Tag key="l" text={`${p.speaks.join(" Â· ")} â†’ ${p.learns}`} />);
  if (tags.length === 0) return null;
  return <div className="flex flex-wrap gap-1.5 mt-3">{tags}</div>;
}

function Tag({ text, accent, green }: { text: string; accent?: boolean; green?: boolean }) {
  const cls = accent
    ? "bg-[#8B5CF6]/15 text-[#8B5CF6]"
    : green
    ? "bg-[#00FF88]/15 text-[#00FF88]"
    : "bg-white/8 text-white/70";
  return <span className={`px-3 py-1 rounded-full text-[11px] font-medium ${cls}`}>{text}</span>;
}

function ExpandedDetails({ profile: p }: { profile: Profile }) {
  return (
    <motion.div
      className="mt-4 pt-4 border-t border-white/8 space-y-3"
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
    >
      {p.speaks && (
        <DetailSection title="Langues">
          <div className="flex gap-1.5">
            {p.speaks.map(l => <span key={l} className="text-[11px] bg-[#06b6d4]/15 px-2.5 py-0.5 rounded-full text-[#06b6d4] font-medium">{l}</span>)}
            {p.learns && <span className="text-[11px] bg-[#8B5CF6]/15 px-2.5 py-0.5 rounded-full text-[#8B5CF6] font-medium">â†’ {p.learns}</span>}
          </div>
        </DetailSection>
      )}
      {p.dog && (
        <DetailSection title="Compagnon">
          <p className="text-[13px] text-white/80">{p.dog} â€” {p.breed}, {p.dogAge}</p>
        </DetailSection>
      )}
      {p.event && (
        <DetailSection title="Event">
          <p className="text-[13px] text-white/80">{p.event}</p>
        </DetailSection>
      )}
    </motion.div>
  );
}

function DetailSection({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <div>
      <p className="text-[9px] text-white/30 uppercase tracking-[0.2em] font-bold mb-1">{title}</p>
      {children}
    </div>
  );
}

"use client";

import { useEffect, useState, useMemo, useRef, useCallback } from "react";
import { motion, AnimatePresence } from "framer-motion";
import Link from "next/link";
import { useGeolocation } from "@/lib/useGeolocation";
import { useAuth } from "@/context/AuthContext";
import { useProfiles } from "@/lib/useProfiles";
import { MOCK_PROFILES, Profile } from "@/lib/mock-profiles";
import { MODES, ModeKey, MODE_KEYS } from "@/lib/modes";
import maplibregl from "maplibre-gl";
import "maplibre-gl/dist/maplibre-gl.css";

function fakePos(lat: number, lng: number, km: number) {
  const r = km / 111;
  return { lat: lat + (Math.random() - 0.5) * 2 * r, lng: lng + (Math.random() - 0.5) * 2 * r };
}

const MODE_COLORS: Record<string, string> = {
  "solo-diner": "#8B5CF6", "plus-one": "#EC4899", "tourist": "#06B6D4",
  "night-owl": "#6366F1", "breakup": "#22C55E", "new-in-town": "#F59E0B",
  "langue": "#06B6D4", "dog-date": "#F59E0B", "seasonal": "#EF4444",
  "fit-date": "#F97316", "foodie-quest": "#DC2626", "culture-club": "#7C3AED",
  "sober-tonight": "#059669", "gamer-night": "#2563EB",
};

interface OpenEvent {
  id: string;
  title: string;
  time: string;
  spots: string;
  lat: number;
  lng: number;
}

interface HeatZone {
  lat: number;
  lng: number;
  intensity: "low" | "medium" | "high";
  radius: number;
}

export default function MapPage() {
  const { user } = useAuth();
  const { position, error, loading } = useGeolocation(user?.id);
  const [filter, setFilter] = useState<ModeKey | "all">("all");
  const [selected, setSelected] = useState<Profile | null>(null);
  const [selectedEvent, setSelectedEvent] = useState<OpenEvent | null>(null);
  const [mounted, setMounted] = useState(false);
  const [showHeatMap, setShowHeatMap] = useState(false);
  const [mapFailed, setMapFailed] = useState(false);
  const mapContainer = useRef<HTMLDivElement>(null);
  const mapRef = useRef<maplibregl.Map | null>(null);
  const markersRef = useRef<maplibregl.Marker[]>([]);
  const eventMarkersRef = useRef<maplibregl.Marker[]>([]);
  const heatMarkersRef = useRef<HTMLDivElement[]>([]);

  const center = position ? { lat: position.lat, lng: position.lng } : { lat: 48.8566, lng: 2.3522 };
  const { profiles: realProfiles } = useProfiles(position?.lat, position?.lng, filter === "all" ? undefined : filter);

  const profilesWithPos = useMemo(() => {
    if (realProfiles.length > 0) {
      return realProfiles.map(p => ({ ...p, pos: { lat: center.lat + (Math.random() - 0.5) * 0.02, lng: center.lng + (Math.random() - 0.5) * 0.02 } }));
    }
    return MOCK_PROFILES.map(p => ({ ...p, pos: fakePos(center.lat, center.lng, p.distance) }));
  }, [realProfiles, center.lat, center.lng]);

  const filtered = filter === "all" ? profilesWithPos : profilesWithPos.filter(p => p.mode === filter);

  // Mock open events
  const openEvents = useMemo<OpenEvent[]>(() => [
    { id: "ev1", title: "Apero chez Marie", time: "20h", spots: "3/8 places", lat: center.lat + 0.005, lng: center.lng + 0.008 },
    { id: "ev2", title: "Soiree jeux Oberkampf", time: "19h30", spots: "5/10 places", lat: center.lat - 0.004, lng: center.lng + 0.003 },
    { id: "ev3", title: "Concert rooftop", time: "21h", spots: "12/20 places", lat: center.lat + 0.007, lng: center.lng - 0.006 },
    { id: "ev4", title: "Diner partage Belleville", time: "20h30", spots: "4/6 places", lat: center.lat - 0.006, lng: center.lng - 0.004 },
  ], [center.lat, center.lng]);

  // Mock heat zones
  const heatZones = useMemo<HeatZone[]>(() => [
    { lat: center.lat + 0.003, lng: center.lng + 0.005, intensity: "high", radius: 120 },
    { lat: center.lat - 0.005, lng: center.lng + 0.002, intensity: "medium", radius: 90 },
    { lat: center.lat + 0.008, lng: center.lng - 0.003, intensity: "high", radius: 100 },
    { lat: center.lat - 0.002, lng: center.lng - 0.007, intensity: "low", radius: 80 },
    { lat: center.lat + 0.001, lng: center.lng + 0.009, intensity: "medium", radius: 110 },
    { lat: center.lat - 0.007, lng: center.lng + 0.006, intensity: "low", radius: 70 },
    { lat: center.lat + 0.006, lng: center.lng + 0.001, intensity: "high", radius: 130 },
    { lat: center.lat - 0.003, lng: center.lng - 0.002, intensity: "medium", radius: 85 },
  ], [center.lat, center.lng]);

  useEffect(() => { setMounted(true); }, []);

  // Init map
  useEffect(() => {
    if (!mounted || !mapContainer.current || mapRef.current) return;

    const map = new maplibregl.Map({
      container: mapContainer.current,
      style: "https://basemaps.cartocdn.com/gl/dark-matter-gl-style/style.json",
      center: [center.lng, center.lat],
      zoom: 13,
      attributionControl: false,
    });

    map.addControl(new maplibregl.NavigationControl({ showCompass: false }), "bottom-right");
    mapRef.current = map;

    // Fallback: if tiles fail to load within 3s, show offline map
    const fallbackTimer = setTimeout(() => {
      if (mapRef.current && !mapRef.current.isStyleLoaded()) {
        setMapFailed(true);
      }
    }, 3000);

    map.on("load", () => {
      clearTimeout(fallbackTimer);
      setMapFailed(false);
    });

    map.on("error", () => {
      setMapFailed(true);
    });

    return () => { clearTimeout(fallbackTimer); map.remove(); mapRef.current = null; };
  }, [mounted, center.lat, center.lng]);

  // Update profile markers
  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;

    markersRef.current.forEach(m => m.remove());
    markersRef.current = [];

    filtered.forEach(p => {
      const color = MODE_COLORS[p.mode] || "#8B5CF6";

      const el = document.createElement("div");
      el.style.cssText = `
        width: 40px; height: 40px; border-radius: 50%; overflow: hidden;
        border: 3px solid ${color}; cursor: pointer;
        box-shadow: 0 0 12px ${color}44;
        transition: transform 0.2s;
      `;
      el.innerHTML = `<img src="${p.photo}" style="width:100%;height:100%;object-fit:cover;" />`;
      el.onmouseenter = () => { el.style.transform = "scale(1.2)"; };
      el.onmouseleave = () => { el.style.transform = "scale(1)"; };
      el.onclick = () => { setSelected(p); setSelectedEvent(null); };

      const marker = new maplibregl.Marker({ element: el })
        .setLngLat([p.pos.lng, p.pos.lat])
        .addTo(map);

      markersRef.current.push(marker);
    });
  }, [filtered]);

  // Update open event markers
  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;

    eventMarkersRef.current.forEach(m => m.remove());
    eventMarkersRef.current = [];

    openEvents.forEach(ev => {
      const el = document.createElement("div");
      el.style.cssText = `
        width: 48px; height: 48px; border-radius: 50%; cursor: pointer;
        background: linear-gradient(135deg, #8B5CF6, #00FF88);
        display: flex; align-items: center; justify-content: center;
        box-shadow: 0 0 20px rgba(139,92,246,0.4);
        animation: pulse-event 2s ease-in-out infinite;
      `;
      el.innerHTML = `<span style="font-size:22px;">ðŸŽ‰</span>`;
      el.onclick = () => { setSelectedEvent(ev); setSelected(null); };

      // Add pulse animation via style tag
      if (!document.getElementById("event-marker-styles")) {
        const style = document.createElement("style");
        style.id = "event-marker-styles";
        style.textContent = `
          @keyframes pulse-event {
            0%, 100% { transform: scale(1); box-shadow: 0 0 20px rgba(139,92,246,0.4); }
            50% { transform: scale(1.1); box-shadow: 0 0 30px rgba(139,92,246,0.6); }
          }
        `;
        document.head.appendChild(style);
      }

      const marker = new maplibregl.Marker({ element: el })
        .setLngLat([ev.lng, ev.lat])
        .addTo(map);

      eventMarkersRef.current.push(marker);
    });
  }, [openEvents]);

  // Heat map overlay
  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;

    // Remove old heat markers
    heatMarkersRef.current.forEach(el => el.remove());
    heatMarkersRef.current = [];

    if (!showHeatMap) return;

    heatZones.forEach(zone => {
      const colors: Record<string, { bg: string; border: string; glow: string }> = {
        low: { bg: "rgba(59,130,246,0.12)", border: "rgba(59,130,246,0.25)", glow: "0 0 20px rgba(59,130,246,0.15)" },
        medium: { bg: "rgba(139,92,246,0.18)", border: "rgba(139,92,246,0.35)", glow: "0 0 30px rgba(139,92,246,0.25)" },
        high: { bg: "rgba(236,72,153,0.22)", border: "rgba(139,92,246,0.45)", glow: "0 0 40px rgba(236,72,153,0.35)" },
      };
      const style = colors[zone.intensity];

      const el = document.createElement("div");
      el.style.cssText = `
        width: ${zone.radius * 2}px; height: ${zone.radius * 2}px;
        border-radius: 50%; pointer-events: none;
        background: radial-gradient(circle, ${style.bg} 0%, transparent 70%);
        border: 1px solid ${style.border};
        box-shadow: ${style.glow};
        ${zone.intensity === "high" ? "animation: heat-pulse 3s ease-in-out infinite;" : ""}
      `;

      if (zone.intensity === "high" && !document.getElementById("heat-pulse-styles")) {
        const styleTag = document.createElement("style");
        styleTag.id = "heat-pulse-styles";
        styleTag.textContent = `
          @keyframes heat-pulse {
            0%, 100% { opacity: 0.7; transform: scale(1); }
            50% { opacity: 1; transform: scale(1.05); }
          }
        `;
        document.head.appendChild(styleTag);
      }

      const marker = new maplibregl.Marker({ element: el, anchor: "center" })
        .setLngLat([zone.lng, zone.lat])
        .addTo(map);

      heatMarkersRef.current.push(el);
      markersRef.current.push(marker);
    });
  }, [showHeatMap, heatZones]);

  if (!mounted) return (
    <div className="h-screen bg-bg flex items-center justify-center">
      <span className="text-3xl text-accent animate-pulse">â˜¾</span>
    </div>
