                  </span>
                  {selected.cuisine && <span className="bg-bg-card border border-border px-2 py-0.5 rounded-full text-[10px] text-text-muted">ðŸ�½ï¸� {selected.cuisine}</span>}
                  {selected.dog && <span className="bg-bg-card border border-border px-2 py-0.5 rounded-full text-[10px] text-text-muted">ðŸ�¶ {selected.dog}</span>}
