@import "tailwindcss";

@theme inline {
  /* WHITE FLUO MINIMAL palette */
  --color-bg: #FFFFFF;
  --color-bg-card: #FAFAFA;
  --color-bg-dark: #111111;
  --color-border: #EBEBEB;
  --color-border-dark: #222222;
  --color-text: #111111;
  --color-text-inv: #FFFFFF;
  --color-text-muted: #767676;
  --color-text-soft: #666666;
  --color-accent: #8B5CF6;
  --color-accent-2: #00FF88;
  --color-safe: #22c55e;
  --color-danger: #ef4444;
  --color-warn: #f59e0b;
  --font-sans: var(--font-outfit), -apple-system, sans-serif;
  --font-display: var(--font-space-grotesk), -apple-system, sans-serif;
}

html { scroll-behavior: smooth; height: -webkit-fill-available; }
body {
  background: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-sans);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
  min-height: -webkit-fill-available;
  overflow-x: hidden;
}
body { padding-top: env(safe-area-inset-top); }

/* === GRADIENTS === */
.gradient-bg { background: linear-gradient(135deg, #8B5CF6, #00FF88); }
.gradient-bg-subtle { background: linear-gradient(135deg, rgba(139,92,246,0.08), rgba(0,255,136,0.08)); }
.gradient-text {
  background: linear-gradient(135deg, #8B5CF6, #00FF88);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
.shadow-glow { box-shadow: 0 0 30px rgba(139,92,246,0.2); }

/* === FOCUS (A11y) === */
*:focus-visible {
  outline: 2px solid #8B5CF6;
  outline-offset: 2px;
}
input:focus-visible, textarea:focus-visible, select:focus-visible {
  outline: none;
  border-color: #8B5CF6;
  box-shadow: 0 0 0 3px rgba(139,92,246,0.15);
}

/* === ANIMATIONS === */
@keyframes fadeUp { from { opacity:0; transform:translateY(12px); } to { opacity:1; transform:translateY(0); } }
@keyframes slideUp { from { transform:translateY(100%); } to { transform:translateY(0); } }
@keyframes float { 0%,100% { transform:translate(0,0); } 50% { transform:translate(15px,-15px); } }
@keyframes shrink { from { width:100%; } to { width:0%; } }

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; }
}

.animate-fade-up { animation: fadeUp 0.4s ease both; }
.animate-slide-up { animation: slideUp 0.35s ease both; }

/* === UTILITY === */
.no-scrollbar::-webkit-scrollbar { display:none; }
.no-scrollbar { scrollbar-width:none; }
.pb-safe { padding-bottom: calc(76px + env(safe-area-inset-bottom)); }
.font-display { font-family: var(--font-display); }
.tap-target { min-height: 44px; min-width: 44px; }

/* === STORY RING === */
.story-ring { padding:2px; background:linear-gradient(135deg,#8B5CF6,#00FF88); border-radius:9999px; }
.story-ring-off { padding:2px; background:#EBEBEB; border-radius:9999px; }

/* === DARK MODE === */
.dark {
  --color-bg: #0A0A0A;
  --color-bg-card: #141414;
  --color-border: #1F1F1F;
  --color-text: #F5F5F5;
  --color-text-inv: #111111;
  --color-text-muted: #888888;
  --color-text-soft: #AAAAAA;
}

.dark .shadow-glow { box-shadow: 0 0 40px rgba(139,92,246,0.35); }
.dark .gradient-bg-subtle { background: linear-gradient(135deg, rgba(139,92,246,0.15), rgba(0,255,136,0.15)); }
.dark .story-ring-off { background: #1F1F1F; }

/* === DARK CARD (for swipe cards) === */
.card-dark { background: #111; color: #fff; }
.card-dark .text-muted-card { color: #888; }
.card-dark .accent-card { color: #00FF88; }

/* === SHIMMER ANIMATION (Skeleton) === */
@keyframes shimmer {
  0% { background-position: -200% 0; }
  100% { background-position: 200% 0; }
}
.animate-shimmer {
  background: linear-gradient(90deg, var(--color-bg-card) 25%, rgba(139,92,246,0.08) 50%, var(--color-bg-card) 75%);
  background-size: 200% 100%;
  animation: shimmer 1.8s ease-in-out infinite;
}

/* === CONFETTI PARTICLE === */
@keyframes confetti-fall {
  0% { opacity: 1; transform: translate(0, 0) rotate(0deg) scale(1); }
  100% { opacity: 0; transform: translate(var(--tx), var(--ty)) rotate(var(--rot)) scale(0.3); }
}

/* === PULSE DOT (badge) === */
@keyframes pulse-dot {
  0%, 100% { transform: scale(1); opacity: 1; }
  50% { transform: scale(1.4); opacity: 0.7; }
}

/* === PAGE TRANSITIONS === */
@keyframes pageEnter {
  from { opacity: 0; transform: translateY(12px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes pageExit {
  from { opacity: 1; transform: translateY(0); }
  to { opacity: 0; transform: translateY(-8px); }
}
.page-enter {
  animation: pageEnter 0.3s ease-out both;
}
.page-exit {
  animation: pageExit 0.2s ease-in both;
}

/* === SWIPE AREA === */
.swipe-area { touch-action: pan-y; }

